//   EAST: the three EMPTY spots stand one step back (y = 17) at 18 m pitch, the planes that came back follow at 22 m. Their boards stand in one line (y = 11.5, beside each nose point),
//         two-faced and fanned, so one lens reads all three from the west (empty_cam), from the east (empty_cam_east) and from the hangar door.
//   WEST: no lane fits between the old row's tails (y 22.5) and the hangar front (y 34) for a 26 m wing. The five west planes stand on a pan one line
//         further south (y = WEST_Y), the lane runs at LANE_Y (wing y 5..31; the door leaves and track guards reach y 33.15) and ends at x = TAXI_X1 before the hero's far wing tip.
const LANE_Y = 18, WEST_Y = -11, TAXI_X1 = -17, EMPTY = [25, 47, 69];
const SPOT_AT = { '-107': [-107, WEST_Y], '-85': [-85, WEST_Y], '-63': [-63, WEST_Y], '-41': [-41, WEST_Y], '-19': [-19, WEST_Y], 25: [31, 17], 47: [49, 17], 69: [67, 17], 91: [89, 17], 113: [111, 17], 135: [133, 17] };
const SXY = xs => SPOT_AT[xs] || [xs, ROW_Y];
const EMPTY_VIEW = { empty_cam: [13.0, 4.3, 1.45], empty_aim: [43.5, 15.7, 6.5], empty_cam_east: [80, -6, 1.45], empty_aim_east: [43.5, 15.9, 5.5], empty_cam_door: [-27, 34.9, 1.45], empty_aim_door: [40, 13, 5], empty_cam_door_wide: [-22.6, 34.95, 1.45], empty_aim_door_wide: [28, 14, 4.5], chief_count: [15.9, 7.0, 0] };   // camera spots that hold all three bare spots (lens: empty_cam 32, east 24, door 50, door_wide 24), and the Chief's mark
const BOARD_AT = { 25: [25.5, 11.5, 5], 47: [43.5, 11.5, -7], 69: [61.5, 11.5, -15] };   // x, y, yaw in degrees: the west face looks along bearing 180 + yaw, the east face along yaw
const NAMES = { '-85': 'PORCH LIGHT', '-63': 'WARM SOCKS', '-41': 'SECOND HELPING', '-19': 'DOOR KEY', 3: 'OLD FAITHFUL', 25: 'LUCKY PENNY', 47: 'HOMESICK', 69: 'BACK BY SUPPER', 91: 'HOME COOKING', 113: 'SAME AGAIN' };
