  const texC = {}, tex = (key, w, h, draw, o = {}) => { const ck = key + (o.rep ? o.rep.join('x') : ''); if (texC[ck]) return texC[ck]; let c = TEX.get(key); if (!c) { c = document.createElement('canvas'); c.width = w; c.height = h; draw(c.getContext('2d'), w, h); TEX.set(key, c); } const t = new THREE.CanvasTexture(c); t.colorSpace = THREE.SRGBColorSpace; t.anisotropy = 8; if (o.rep) { t.wrapS = t.wrapT = THREE.RepeatWrapping; t.repeat.set(o.rep[0], o.rep[1]); } return (texC[ck] = t); };
