  const C = { olive: '#627236', oliveD: '#48562a', oliveL: '#7a8c42', khaki: '#b3a06a', tan: '#c9b384', brown: '#7a5334', brownD: '#553823', timber: '#a47e56', timberD: '#826244', timberL: '#c09c70',
    cream: '#e6dcc0', white: '#eee9dc', iron: '#34363a', steel: '#8492a2', steelL: '#b2c2d2', brass: '#d9a93c', maroon: '#6e3a3a', yellow: '#f2bc1e', yellowD: '#c28e12', blue: '#2f5fb8',
    rubber: '#2e2823', conc: '#c0b297', concD: '#988a72', canvas: '#8d8a5c', canvasD: '#6f6d48', burlap: '#b99f6c', rust: '#7b4a2c', glass: '#a9cfe2', tin: '#9aa4a2', tinD: '#77827f', brick: '#9a6a4c', roof: '#3d4240', slate: '#27332f' };
